import java.util.*;

public class Test {
    static void fill(List<? super Integer> list) { list.add(42); }
    static double total(List<? extends Number> list) {
        double t = 0;
        for (Number n : list) t += n.doubleValue();
        return t;
    }
    public static void main(String[] args) {
        List<Number> nums = new ArrayList<>();
        fill(nums);                        // line 1
        List<Object> objs = new ArrayList<>();
        fill(objs);                        // line 2
        System.out.println(total(nums));   // line 3
        List<Integer> ints = List.of(1, 2);
        System.out.println(total(ints));   // line 4
        fill(ints);                        // line 5
    }
}
